#!/usr/bin/env bash
# One-off: creates vaults/Kubernetes/items/timescale-grafana for Grafana's
# read-only grafana role on the TimescaleDB cluster (core/timescale). The
# password is generated by 1Password and never printed.
set -euo pipefail

eval "$(op signin)"
op item create --vault Kubernetes --category login --title timescale-grafana \
  --generate-password='letters,digits,32' \
  username=grafana >/dev/null
echo "created: timescale-grafana"
